INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q6864869', 'Ming–Kotte War', 'The Ming–Kotte War was a military conflict between the expeditionary forces of Ming China and the Sinhalese Kotte Kingdom in the southern territories of Sri Lanka. The conflict happened when Ming China''s treasure fleet arrived at Sri Lanka in 1410 or 1411.', 1410, NULL, NULL, 1411, NULL, NULL, 'year', '1410–1411', 43, 'https://en.wikipedia.org/wiki/Ming%E2%80%93Kotte_War'),
  ('Q17034772', 'Sinhalese–Portuguese conflicts', 'Between 1518 and 1658, armed conflict took place between the native Sinhalese kingdoms of Sri Lanka (then known to Europeans as Ceylon), and the Portuguese Empire. It spanned from the Transitional to the Kandyan periods of Sri Lankan history.', 1527, NULL, NULL, 1658, NULL, NULL, 'year', '1527–1658', 34, 'https://en.wikipedia.org/wiki/Sinhalese%E2%80%93Portuguese_conflicts'),
  ('Q15277679', 'Siege of Galle', 'The Siege of the Portuguese fort Santa Cruz de Gale at Galle in 1640, took place during the Dutch–Portuguese and Sinhalese–Portuguese Wars. The Galle fort commanded 282 villages, which contained the most fertile cinnamon lands in southern Sri Lanka It was also an important strategic coastal defense of Portuguese Ceylon.', 1640, 3, 8, 1640, 3, 13, 'day', '8 March 1640 – 13 March 1640', 34, 'https://en.wikipedia.org/wiki/Siege_of_Galle_(1640)'),
  ('Q2601158', 'Battle of Trincomalee', 'The Battle of Trincomalee was fought between a British fleet under Vice-Admiral Sir Edward Hughes and a French fleet under the Bailli de Suffren off the coast of Trincomalee, then Ceylon (modern Sri Lanka), on 3 September 1782. It was the fourth in a series of battles fought between the two fleets off the coast of the Indian subcontinent during the American Revolutionary War.', 1782, 8, 25, 1782, 9, 3, 'day', '25 August 1782 – 3 September 1782', 41, 'https://en.wikipedia.org/wiki/Battle_of_Trincomalee'),
  ('Q2601189', 'Battle of Providien', 'The Battle of Providien was the second in a series of naval battles fought between a British fleet, under Vice-Admiral Sir Edward Hughes, and a French fleet, under the Bailli de Suffren, off the coast of India during the Anglo-French War. The battle was fought on 12 April 1782 off the east coast of Ceylon, near a rocky islet called Providien, south of Trincomalee.', 1782, 4, 12, NULL, NULL, NULL, 'day', '12 April 1782', 43, 'https://en.wikipedia.org/wiki/Battle_of_Providien'),
  ('Q3534806', 'Great Rebellion of 1817–1818', 'The Great Rebellion of 1817–1818 (Sinhala: ඌව වෙල්ලස්ස මහා කැරැල්ල), also known as the 1818 Uva-Wellassa Rebellion (after the two places where it had started), was the third Kandyan War in the Uva and Wellassa provinces of the former Kingdom of Kandy, which is today the Uva province of Sri Lanka. The rebellion started against the British colonial government under Governor Robert Brownrigg, three years after the Kandyan Convention ceded the Kingdom of Kandy to the British Crown.', 1817, NULL, NULL, 1818, NULL, NULL, 'year', '1817–1818', 37, 'https://en.wikipedia.org/wiki/Great_Rebellion_of_1817%E2%80%931818'),
  ('Q4204647', '1833 Sumatra earthquake', 'The 1833 Sumatra earthquake occurred on November 25 at about 22:00 local time, with an estimated magnitude in the range of 8.8–9.2 Mw. It caused a large tsunami that flooded the southwestern coast of the island.', 1833, NULL, NULL, NULL, NULL, NULL, 'year', '1833', 41, 'https://en.wikipedia.org/wiki/1833_Sumatra_earthquake'),
  ('Q5339486', 'Matale Rebellion', 'The Matale rebellion, also known as the Rebellion of 1848, took place in Matale city, Ceylon against the British colonial government under Governor George Byng, 7th Viscount Torrington. It marked a transition from the classic feudal form of anti-colonial revolt to modern independence struggles.', 1848, NULL, NULL, NULL, NULL, NULL, 'year', '1848', 30, 'https://en.wikipedia.org/wiki/Matale_rebellion'),
  ('Q757871', 'Indian Ocean raid', 'The Indian Ocean raid (Operation C, the Third Mobile Operation in the Indian Ocean and the Battle of Ceylon in Japanese) was a sortie of the Imperial Japanese Navy (IJN) from 31 March to 10 April 1942. Japanese aircraft carriers (Admiral Chūichi Nagumo) struck Allied shipping, naval bases and airfields around British Ceylon but failed to find most of the Eastern Fleet.', 1942, 3, 31, 1942, 4, 10, 'day', '31 March 1942 – 10 April 1942', 63, 'https://en.wikipedia.org/wiki/Indian_Ocean_raid'),
  ('Q12974823', 'Tamil genocide', 'The Tamil genocide refers to the framing of various systematic acts of physical violence and cultural destruction committed against the Tamil population in Sri Lanka during the Sinhala–Tamil ethnic conflict beginning in 1956, particularly during the Sri Lankan civil war as acts of genocide. Various commenters, including the Permanent Peoples'' Tribunal, have accused the Sri Lankan government of responsibility for and complicity in a genocide of Tamils, and point to state-sponsored settler colonialism, state-backed pogroms, and mass killings, enforced disappearances and sexual violence by the…', 1956, NULL, NULL, 2009, NULL, NULL, 'year', '1956–2009', 37, 'https://en.wikipedia.org/wiki/Tamil_genocide'),
  ('Q4207890', 'Martinair Flight 138', 'Martinair Flight 138 was a charter flight of Martinair from Surabaya to Jeddah with a stopover in Colombo. On 4 December 1974, the Douglas DC-8 operating the flight crashed into a mountain in Sri Lanka shortly before landing, killing all 191 people aboard – 182 passengers, all of whom were Indonesian Hajj pilgrims, and nine crew members.', 1974, 12, 4, NULL, NULL, NULL, 'day', '4 December 1974', 56, 'https://en.wikipedia.org/wiki/Martinair_Flight_138'),
  ('Q5985739', 'Icelandic Airlines Flight 001', 'Loftleiðir Flight 001 was a Hajj charter flight operated by a Douglas DC-8 which crashed on approach to Colombo, Sri Lanka, on 15 November 1978. The crash killed 183 out of 262 passengers and crew members.', 1978, 11, 15, NULL, NULL, NULL, 'day', '15 November 1978', 56, 'https://en.wikipedia.org/wiki/Loftlei%C3%B0ir_Flight_001'),
  ('Q7586113', 'Sri Lankan national referendum, 1982', 'A referendum on extending the term of parliament by six years was held in Sri Lanka on 22 December 1982. It was the first and so far only national referendum to be held in the country.', 1982, 12, 22, NULL, NULL, NULL, 'day', '22 December 1982', 34, 'https://en.wikipedia.org/wiki/1982_Sri_Lankan_parliamentary_term_extension_referendum'),
  ('Q213394', 'Sri Lankan Civil War', 'A civil war was fought in Sri Lanka from 1983 to 2009. Beginning on 23 July 1983, it was an intermittent insurgency against the government by the Liberation Tigers of Tamil Eelam (LTTE, also known as the Tamil Tigers) led by Velupillai Prabhakaran.', 1983, 7, 23, 2009, 5, 18, 'day', '23 July 1983 – 18 May 2009', 76, 'https://en.wikipedia.org/wiki/Sri_Lankan_civil_war'),
  ('Q1814745', 'Eelam War I', 'Eelam War I (23 July 1983 – 29 July 1987) is the name given to the initial phase of the Sri Lankan civil war between the government of Sri Lanka and the LTTE.', 1983, 7, 23, 1987, 7, 29, 'day', '23 July 1983 – 29 July 1987', 39, 'https://en.wikipedia.org/wiki/Eelam_War_I'),
  ('Q4698060', 'Air Lanka Flight 512', 'Air Lanka Flight 512 was an Air Lanka (now SriLankan Airlines) flight from London Gatwick Airport via Zurich and Dubai to Colombo (Bandaranaike International Airport) and Malé, Maldives (Malé International Airport, now Velana International Airport). On 3 May 1986, the Lockheed L-1011 Tristar serving the flight was on the ground in Colombo, about to fly on to Malé, when an explosion ripped the aircraft in two, destroying it.', 1986, 5, 3, NULL, NULL, NULL, 'day', '3 May 1986', 45, 'https://en.wikipedia.org/wiki/Air_Lanka_Flight_512'),
  ('Q4584263', '1987–89 JVP Insurrection', 'The 1987–1989 JVP insurrection, also known as the 1988–1989 revolt, was an armed revolt in Sri Lanka led by the Marxist–Leninist Janatha Vimukthi Peramuna (JVP) against the Government of Sri Lanka, then led by the right-wing United National Party (UNP). The insurrection, like the previous one in 1971, was unsuccessful.', 1987, NULL, NULL, 1989, NULL, NULL, 'year', '1987–1989', 39, 'https://en.wikipedia.org/wiki/1987%E2%80%931989_JVP_insurrection'),
  ('Q3522435', 'Kattankudy mosque massacre', 'The Kattankudy Mosque Massacre was the killing of over 147 Muslim men and boys on 3 August, 1990. Around 30 armed Tamil militants raided two mosques in Kattankudy (Meer Jummah Mosque, Kattankudy-01 & Hussainiyya Mosque, Manchanthoduwai) where over 300 people were prostrating in Isha prayers.', 1990, 8, 3, NULL, NULL, NULL, 'day', '3 August 1990', 41, 'https://en.wikipedia.org/wiki/Kattankudy_mosque_massacre'),
  ('Q4586462', '1990 massacre of Sri Lankan Police officers', 'On 11 June 1990, the militant organisation Liberation Tigers of Tamil Eelam (LTTE) carried out a massacre of unarmed police officers in Sri Lanka''s Eastern Province. LTTE members allegedly killed over 600 officers that day.', 1990, 6, 11, NULL, NULL, NULL, 'day', '11 June 1990', 37, 'https://en.wikipedia.org/wiki/1990_massacre_of_Sri_Lankan_Police_officers'),
  ('Q11050383', 'Eelam War II', 'Eelam War II refers to the second phase of the Sri Lankan civil war between the Sri Lankan military and the Liberation Tigers of Tamil Eelam, lasting from June 1990 to 1995. The war erupted after the breakdown of peace talks between the LTTE and the government of President Ranasinghe Premadasa, during which mutual distrust and provocations escalated tensions.', 1990, NULL, NULL, 1995, 1, 9, 'year', '1990 – 9 January 1995', 37, 'https://en.wikipedia.org/wiki/Eelam_War_II'),
  ('Q7127928', 'Palliyagodella massacre', 'The Palliyagodella massacre was carried out by the Liberation Tigers of Tamil Eelam (LTTE) against the mostly Muslim population of the Palliyagodella village located on border region of the northern part of Sri Lanka that were controlled by the Tigers at the time. This was the largest massacre of Muslim civilians by the LTTE to date.', 1992, 10, 15, NULL, NULL, NULL, 'day', '15 October 1992', 37, 'https://en.wikipedia.org/wiki/Palliyagodella_massacre'),
  ('Q11154636', 'Eelam War III', 'Eelam War III is the name given to the third phase of the Sri Lankan civil war between the Sri Lankan military and the separatist Liberation Tigers of Tamil Eelam (LTTE). After the period of 100 days cease-fire the hostilities broke out on 19 April 1995.', 1995, NULL, NULL, 2002, 2, 22, 'year', '1995 – 22 February 2002', 39, 'https://en.wikipedia.org/wiki/Eelam_War_III'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q4570436', '2006 Trincomalee massacre of NGO workers', 'The Muttur Massacre was an incident that occurred on 4 August 2006 in Muttur, Sri Lanka, in the district of Trincomalee, during the Sri Lankan civil war. Seventeen local employees of the French non-governmental organization Action Against Hunger were executed at close range inside their office.', 2006, 8, 4, NULL, NULL, NULL, 'day', '4 August 2006', 39, 'https://en.wikipedia.org/wiki/2006_Trincomalee_massacre_of_NGO_workers'),
  ('Q16151540', 'Eelam War IV', 'Eelam War IV was the fourth and final phase of armed conflict between the Sri Lankan military and the separatist Liberation Tigers of Tamil Eelam (LTTE). Renewed hostilities began on the 26 July 2006, when Sri Lanka Air Force fighter jets bombed several LTTE camps around Mavil Aru anicut, with the casus belli being that the LTTE had cut off the water supply to surrounding paddy fields in the area.', 2006, 7, 26, 2009, 5, 18, 'day', '26 July 2006 – 18 May 2009', 37, 'https://en.wikipedia.org/wiki/Eelam_War_IV'),
  ('Q2572835', '2008–2009 Battle of Kilinochchi', 'The Battle of Kilinochchi was a land battle fought between the Sri Lankan Military and the Liberation Tigers of Tamil Eelam (LTTE) for control of the town of Kilinochchi in the Northern Theatre of Eelam War IV during the Sri Lankan civil war between November 2008 and January 2009. The town of Kilinochchi was the administrative center and de facto capital of the LTTE''s proposed state of Tamil Eelam.', 2008, 11, 23, 2009, 1, 2, 'day', '23 November 2008 – 2 January 2009', 43, 'https://en.wikipedia.org/wiki/Battle_of_Kilinochchi_(2008%E2%80%932009)'),
  ('Q373857', 'Battle of Mullaitivu', 'The Battle of Mullaitivu (Sinhala: මුලතිව් සටන) was a land battle fought between the Sri Lankan Military and the Liberation Tigers of Tamil Eelam (LTTE) for the control of the town of Mullaitivu in the Northern Theatre of Eelam War IV during the Sri Lankan civil war. The town of Mullaitivu was the last stronghold of the LTTE. The government declared on 25 January 2009 that its troops had entered the town and were consolidating their positions.', 2009, 1, 2, 2009, 1, 25, 'day', '2 January 2009 – 25 January 2009', 37, 'https://en.wikipedia.org/wiki/Battle_of_Mullaitivu_(2009)'),
  ('Q20987498', 'Tamil Massacre in 2009', 'The Mullivaikkal massacre was the mass killing of tens of thousands of Sri Lankan Tamils in 2009 during the closing stages of the Sri Lankan Civil War, which ended in May 2009 in a tiny strip of land in Mullivaikkal, Mullaitivu. The Sri Lankan government had designated no-fire zones in the Vanni region towards the end of the war.', 2009, 5, NULL, NULL, NULL, NULL, 'month', 'May 2009', 34, 'https://en.wikipedia.org/wiki/Mullivaikkal_massacre'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q111458253', 'Aragalaya', 'The Aragalaya (Sinhala: අරගලය, lit. ''The Struggle'') were a series of mass protests that began in March 2022 against the government of Sri Lanka. The government was heavily criticized for mismanaging the Sri Lankan economy, which led to a subsequent economic crisis involving severe inflation, daily blackouts, and a shortage of fuel, domestic gas, and other essential goods.', 2022, 3, 15, 2022, 11, 14, 'day', '15 March 2022 – 14 November 2022', 67, 'https://en.wikipedia.org/wiki/Aragalaya');
